window.kbPageData["views/entry/k-bbfcc1599e79a235"] = {"key":"entry/k-bbfcc1599e79a235","state":{"route":"entry/k-bbfcc1599e79a235"},"node":{"id":"k-bbfcc1599e79a235","mode":"k","title":"矛盾的普遍性、特殊性和客观性","type":"原理与机制","domain":"哲学","reading":"","intro":"","priority":100,"aliases":["辩证法 · 三大规律","唯物辩证法的三大规律"],"qs":["国考 2025 副省级 行测#2","国考 2025 地市级 行测#2","国考 2025 行政执法 行测#2"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":2,"reviewSet":"多题条目","independentCount":1,"tags":{"主类":["原理与机制"],"出处性质":["理论手册"],"学科":["哲学"],"来源主题":["马克思主义哲学"],"资料类别":["非时政"]},"seeAlso":["k-15e08a19cc250aed","k-2ea1431b5ab948ff"],"directorySummary":"在唯物辩证法的对立统一规律中，矛盾的普遍性指矛盾贯穿一切事物的发展过程，体现为共性。特殊性指具体矛盾各有特点，体现为个性。客观性指矛盾的存在不以人的意志为转移。","review":{"title":"矛盾的普遍性、特殊性和客观性","type":"原理与机制","definition":"在唯物辩证法的对立统一规律中，矛盾的普遍性指矛盾贯穿一切事物的发展过程，体现为共性。特殊性指具体矛盾各有特点，体现为个性。客观性指矛盾的存在不以人的意志为转移。","explanation":"共性寓于个性之中。不同事物、同一事物的不同发展阶段以及同一矛盾的不同方面，各有具体特点。分析这些特点是认识事物性质和发展规律的基础。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"国考 2025 副省级 行测#2":"比较各项陈述对矛盾性质、存在条件及其与人的认识关系的界定。"}},"aspects":[{"title":"矛盾的共性、个性与客观存在","uses":[{"unit":"Q1","role":"直接考查","use":"题干以问题导向引出矛盾的普遍性和客观性。C项正确对应共性与个性。A项把具体矛盾随条件变化的特点归给普遍性，B项把客观存在归于主观认知，D项把矛盾特殊性在区分事物性质中的作用归给了普遍性和客观性。","evidence":"矛盾的普遍性是矛盾的共性，矛盾的特殊性是矛盾的个性","qids":["国考 2025 副省级 行测#2","国考 2025 地市级 行测#2","国考 2025 行政执法 行测#2"]}]}],"sources":[{"id":"c394cdef1420fc60","label":"辩证法 · 三大规律","topic":"马克思主义哲学","category":"非时政","text":"二、三大规律\n1.对立统一规律\n（1）含义：对立统一规律是唯物辩证法的实质和核心；对立统一规律揭示了事物发展\n的源泉和动力。\n（2）矛盾的基本属性\n同一性是指矛盾双方相互依存、相互贯通，在一定条件下可以相互转化。\n斗争性是指矛盾双方相互排斥的属性，体现着对立双方相互分离的倾向和趋势。\n（3）矛盾的普遍性和特殊性\n矛盾的普遍性是指时时有矛盾、事事有矛盾，矛盾的普遍性要求我们运用矛盾分析法分\n析一切事物。\n矛盾的特殊性是指具体事物包含的矛盾以及每一矛盾的各个方面都有其特点，矛盾的特\n殊性要求我们要具体问题具体分析。\n（粉笔敲黑板：通俗来讲，普遍性强调的是“都有”，特殊性强调的是“不一样”\n）\n（4）矛盾的不平衡性\n①主要矛盾和次要矛盾\n主要矛盾是指在诸多矛盾中处于支配地位、对事物发展起决定作用的矛盾；次要矛盾是\n指处于从属地位、对事物发展不起决定作用的矛盾。\n②矛盾的主要方面和次要方面\n矛盾的主要方面是一个矛盾中处于支配地位、起主导作用的方面；矛盾的次要方面是处\n于被支配地位的方面。\n矛盾发展的不平衡性要求我们做到两点论和重点论的统一。\n（4）内因和外因的关系\n内因是事物变化发展的根据和第一位原因。\n外因是事物变化发展的条件，外因通过内因起作用。\n事物的发展是内外因共同作用的结果。\n（粉笔敲黑板：对立统一规律属于马克思主义哲学中的重要考点，要求能够理解相关哲\n学原理，且能够通过选项案例判断哲理是否对应正确）\n2.质量互变规律\n质量互变规律揭示了事物发展的形式和状态。\n辩证关系：量变是质变的前提和必要准备；质变是量变的必然结果。\n方法论：坚持适度原则；重视量的积累；不失时机地促成质变，实现事物的飞跃。\n3.否定之否定规律\n否定之否定规律揭示了事物发展的方向和道路。\n任何事物的发展都要经历“肯定→否定→否定之否定”的过程。\n事物的发展是前进性和曲折性的统一。\n（粉笔敲黑板：本考点主要结合古语和案例考查，“前进性”强调的是方向美好，曲折\n性强调的是“道路曲折”）","source":{"doc":"3ccc56f4000d1642c2d1","first":3,"last":5,"page":3,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{"国考 2025 副省级 行测#2":{"paper":"国考 2025 副省级 行测","n":2,"mod":"政治理论","src":["ffe12c35a46d4df574ec.pdf",1],"asrc":["ff0b352b44d417525086.pdf",1],"card":"9b8abfaad5ead8c42cff2c9f","links":[{"id":"k-bbfcc1599e79a235","role":"直接考查","why":"题目具体考查对立统一规律中矛盾的共性与个性，以及矛盾不以人的意志为转移的客观性。"}]},"国考 2025 地市级 行测#2":{"paper":"国考 2025 地市级 行测","n":2,"mod":"政治理论","src":["31f401e91aef8d11365d.pdf",1],"asrc":["8cece062c7c079b53130.pdf",1],"card":"96becde8184deb351eaa5ba4","links":[{"id":"k-bbfcc1599e79a235","role":"直接考查","why":"题目考查对立统一规律中矛盾的共性和个性，并要求区分矛盾的客观性与特殊性的作用。"}]},"国考 2025 行政执法 行测#2":{"paper":"国考 2025 行政执法 行测","n":2,"mod":"政治理论","src":["d8efe4e19862104d89c8.pdf",1],"asrc":["e2c4b1970d2b49eac0fd.pdf",1],"card":"336f02923851603a0b694fe9","links":[{"id":"k-bbfcc1599e79a235","role":"直接考查","why":"本题考查对立统一规律中的共性与个性关系，以及矛盾不以人的意志为转移的客观性。"}]}},"terms":{"k-15e08a19cc250aed":{"id":"k-15e08a19cc250aed","mode":"k","type":"原理与机制","title":"矛盾的主要方面","qs":[],"count":0},"k-2ea1431b5ab948ff":{"id":"k-2ea1431b5ab948ff","mode":"k","type":"原理与机制","title":"主要矛盾","qs":[],"count":1}},"references":{},"topics":[],"units":{"k-bbfcc1599e79a235":[["国考 2025 副省级 行测#2","国考 2025 地市级 行测#2","国考 2025 行政执法 行测#2"]]}};
